document.addEventListener("DOMContentLoaded",function(){
    /* ===== DOM REFERENCES (all IDs preserved) ===== */
    var fileInput=document.getElementById("file-input"),
        settingsPanel=document.getElementById("settings-panel"),
        resizeBtn=document.getElementById("resize-btn"),
        downloadBtn=document.getElementById("download-btn"),
        resetBtn=document.getElementById("reset-btn"),
        previewContainer=document.getElementById("image-preview-container"),
        progressSection=document.getElementById("progress-section"),
        progressFill=document.getElementById("progress-fill"),
        progressPercent=document.getElementById("progress-percent"),
        progressText=document.getElementById("progress-text"),
        resizeMode=document.getElementById("resize-mode"),
        resizeWidth=document.getElementById("resize-width"),
        resizeHeight=document.getElementById("resize-height"),
        resizePercent=document.getElementById("resize-percent"),
        percentValue=document.getElementById("percent-value"),
        keepAspect=document.getElementById("keep-aspect"),
        outputFormat=document.getElementById("output-format"),
        qualitySlider=document.getElementById("quality"),
        qualityValue=document.getElementById("quality-value"),
        newDims=document.getElementById("new-dims"),
        originalDims=document.getElementById("original-dims"),
        upscaleWarning=document.getElementById("upscale-warning"),
        transparencyWarning=document.getElementById("transparency-warning"),
        resultSection=document.getElementById("result-section"),
        resultInfo=document.getElementById("result-info"),
        resultPreview=document.getElementById("result-preview"),
        resultDownloadBtn=document.getElementById("result-download-btn");

    /* ===== STATE ===== */
    var originalFile=null,
        loadedImage=null,
        originalW=0,
        originalH=0,
        blobURL=null;

    /* ===== PICA INITIALIZATION ===== */
    var picaEngine=null;
    if(typeof Pica!=="undefined"){
        picaEngine=new Pica({
            features:["js","wasm","cib","webgl","webgl2"],
            cacheSize:16384,
            idle:100
        });
    }

    /* ===== CANVAS SIZE LIMITS ===== */
    var MAX_CANVAS_AREA=16384*16384;

    /* ===== UTILITY: NOTIFICATION ===== */
    function notify(msg,isError){
        var existing=document.querySelector(".notification");
        if(existing)existing.remove();
        var el=document.createElement("div");
        el.className="notification"+(isError?" error":"");
        el.textContent=msg;
        document.body.appendChild(el);
        setTimeout(function(){el.remove()},4000);
    }

    /* ===== UTILITY: FORMAT FILE SIZE ===== */
    function formatSize(bytes){
        if(!bytes||bytes===0)return"0 Bytes";
        var u=["Bytes","KB","MB","GB"];
        var i=Math.floor(Math.log(bytes)/Math.log(1024));
        return parseFloat((bytes/Math.pow(1024,i)).toFixed(2))+" "+u[i];
    }

    /* ===== UTILITY: CHECK IF IMAGE HAS TRANSPARENCY ===== */
    function hasTransparency(img){
        try{
            var c=document.createElement("canvas");
            c.width=img.naturalWidth;
            c.height=img.naturalHeight;
            var ctx=c.getContext("2d");
            ctx.drawImage(img,0,0);
            var data=ctx.getImageData(0,0,c.width,c.height).data;
            for(var i=3;i<data.length;i+=4){
                if(data[i]<255)return true;
            }
        }catch(e){}
        return false;
    }

    /* ===== WARNING MANAGEMENT ===== */
    function updateWarnings(){
        if(!loadedImage)return;
        var mode=resizeMode.value;
        var tw=parseInt(resizeWidth.value)||originalW;
        var th=parseInt(resizeHeight.value)||originalH;
        if(mode==="percentage"){
            var pct=parseInt(resizePercent.value)||50;
            tw=Math.round(originalW*pct/100);
            th=Math.round(originalH*pct/100);
        }
        /* Upscale warning */
        if(tw>originalW||th>originalH){
            upscaleWarning.style.display="flex";
        }else{
            upscaleWarning.style.display="none";
        }
        /* Transparency warning (PNG source → JPEG output) */
        var fmt=outputFormat.value;
        if(originalFile&&originalFile.type==="image/png"&&fmt==="image/jpeg"){
            if(hasTransparency(loadedImage)){
                transparencyWarning.style.display="flex";
            }else{
                transparencyWarning.style.display="none";
            }
        }else{
            transparencyWarning.style.display="none";
        }
    }

    /* ===== PROGRESS UPDATE ===== */
    function setProgress(pct,text){
        progressFill.style.width=pct+"%";
        progressPercent.textContent=Math.round(pct)+"%";
        if(text)progressText.textContent=text;
    }

    /* ===== DIMENSION CALCULATION ===== */
    function updateDimensions(){
        if(!loadedImage)return;
        var mode=resizeMode.value;
        var tw=originalW,th=originalH;
        if(mode==="width"){
            tw=parseInt(resizeWidth.value)||originalW;
            if(keepAspect.checked){
                th=Math.round(tw*(originalH/originalW));
                resizeHeight.value=th;
            }else{
                th=parseInt(resizeHeight.value)||originalH;
            }
        }else if(mode==="height"){
            th=parseInt(resizeHeight.value)||originalH;
            if(keepAspect.checked){
                tw=Math.round(th*(originalW/originalH));
                resizeWidth.value=tw;
            }else{
                tw=parseInt(resizeWidth.value)||originalW;
            }
        }else if(mode==="percentage"){
            var pct=parseInt(resizePercent.value)||50;
            tw=Math.round(originalW*pct/100);
            th=Math.round(originalH*pct/100);
            resizeWidth.value=tw;
            resizeHeight.value=th;
        }
        newDims.textContent=tw+" x "+th;
        updateWarnings();
    }

    /* ===== DRAG & DROP ===== */
    var dropArea=document.querySelector(".upload-area");
    if(dropArea){
        dropArea.addEventListener("dragover",function(e){
            e.preventDefault();
            dropArea.classList.add("dragover");
        });
        dropArea.addEventListener("dragleave",function(){
            dropArea.classList.remove("dragover");
        });
        dropArea.addEventListener("drop",function(e){
            e.preventDefault();
            dropArea.classList.remove("dragover");
            if(e.dataTransfer.files.length){
                fileInput.files=e.dataTransfer.files;
                fileInput.dispatchEvent(new Event("change"));
            }
        });
    }

    /* ===== MODE SWITCHING ===== */
    resizeMode.addEventListener("change",function(){
        var mode=resizeMode.value;
        document.getElementById("dimension-fields").style.display=mode==="percentage"?"none":"";
        document.getElementById("percent-field").style.display=mode==="percentage"?"":"none";
        updateDimensions();
    });
    resizeWidth.addEventListener("input",function(){
        if(resizeMode.value==="width")updateDimensions();
    });
    resizeHeight.addEventListener("input",function(){
        if(resizeMode.value==="height")updateDimensions();
    });
    resizePercent.addEventListener("input",function(){
        percentValue.textContent=resizePercent.value+"%";
        if(resizeMode.value==="percentage")updateDimensions();
    });
    keepAspect.addEventListener("change",function(){
        if(resizeMode.value==="width"||resizeMode.value==="height")updateDimensions();
    });
    qualitySlider.addEventListener("input",function(){
        qualityValue.textContent=qualitySlider.value+"%";
    });
    outputFormat.addEventListener("change",function(){
        updateWarnings();
    });

    /* ===== PREVIEW RENDER ===== */
    function renderPreview(){
        if(!loadedImage)return;
        previewContainer.innerHTML="";
        var canvas=document.createElement("canvas");
        canvas.style.maxWidth="100%";
        canvas.style.borderRadius="8px";
        previewContainer.appendChild(canvas);
        var containerW=previewContainer.clientWidth||400;
        var scale=Math.min(1,containerW/loadedImage.naturalWidth);
        canvas.width=loadedImage.naturalWidth*scale;
        canvas.height=loadedImage.naturalHeight*scale;
        var ctx=canvas.getContext("2d");
        ctx.clearRect(0,0,canvas.width,canvas.height);
        ctx.drawImage(loadedImage,0,0,canvas.width,canvas.height);
    }

    /* ===== FILE INPUT HANDLER ===== */
    fileInput.addEventListener("change",function(e){
        var file=e.target.files[0];
        if(!file)return;
        if(!file.type.match(/^image\/(jpeg|png|webp)$/)){
            notify("Please select a JPG, PNG, or WebP image",true);
            return;
        }
        /* Check file size (200MB limit) */
        if(file.size>200*1024*1024){
            notify("File too large. Maximum size is 200 MB.",true);
            return;
        }
        originalFile=file;
        var img=new Image();
        img.onload=function(){
            /* Verify decoded dimensions */
            if(!img.naturalWidth||!img.naturalHeight){
                notify("Failed to decode image. The file may be corrupted.",true);
                return;
            }
            /* Canvas size limit check */
            if(img.naturalWidth*img.naturalHeight>MAX_CANVAS_AREA){
                notify("Image too large for browser processing. Maximum is ~268 megapixels.",true);
                return;
            }
            loadedImage=img;
            originalW=img.naturalWidth;
            originalH=img.naturalHeight;
            previewContainer.innerHTML="";
            renderPreview();
            originalDims.textContent=originalW+" x "+originalH;
            resizeWidth.value=originalW;
            resizeHeight.value=originalH;
            settingsPanel.classList.add("show");
            resizeBtn.disabled=false;
            updateDimensions();
        };
        img.onerror=function(){
            notify("Failed to load image. The file may be corrupted or unsupported.",true);
        };
        try{
            img.src=URL.createObjectURL(file);
        }catch(err){
            notify("Failed to read file: "+err.message,true);
        }
    });

    /* ===== RESIZE ENGINE: PICA ===== */
    resizeBtn.addEventListener("click",function(){
        if(!loadedImage)return;
        var tw=parseInt(resizeWidth.value)||originalW;
        var th=parseInt(resizeHeight.value)||originalH;
        if(tw<1||th<1){
            notify("Dimensions must be at least 1 pixel",true);
            return;
        }
        /* Canvas size limit check before resize */
        if(tw*th>MAX_CANVAS_AREA){
            notify("Target size too large. Maximum canvas area is ~268 megapixels.",true);
            return;
        }
        progressSection.style.display="block";
        resizeBtn.disabled=true;
        resultSection.style.display="none";
        resultPreview.src="";
        setProgress(5,"Preparing image...");

        /* Source canvas: draw original at full resolution */
        var srcCanvas=document.createElement("canvas");
        srcCanvas.width=originalW;
        srcCanvas.height=originalH;
        var srcCtx=srcCanvas.getContext("2d",{alpha:true});
        srcCtx.drawImage(loadedImage,0,0);

        setProgress(15,"Resizing with high-quality resampling...");

        /* Destination canvas */
        var dstCanvas=document.createElement("canvas");
        dstCanvas.width=tw;
        dstCanvas.height=th;

        if(picaEngine){
            /* ===== PICA HIGH-QUALITY RESIZE ===== */
            picaEngine.resize(srcCanvas,dstCanvas,{
                quality:3,
                alpha:true,
                unsharpAmount:0.8,
                unsharpRadius:0.6,
                unsharpThreshold:1,
                transferable:true
            }).then(function(){
                setProgress(75,"Encoding image...");
                encodeAndFinalize(dstCanvas,tw,th);
            }).catch(function(err){
                console.error("Pica resize failed, falling back to canvas:",err);
                setProgress(40,"Pica failed, using fallback...");
                fallbackResize(srcCanvas,dstCanvas,tw,th);
            });
        }else{
            /* ===== FALLBACK: Native canvas (Pica not loaded) ===== */
            setProgress(40,"Using native canvas (Pica unavailable)...");
            fallbackResize(srcCanvas,dstCanvas,tw,th);
        }
    });

    /* ===== FALLBACK RESIZE ===== */
    function fallbackResize(src,dst,w,h){
        var ctx=dst.getContext("2d",{alpha:true});
        ctx.imageSmoothingEnabled=true;
        ctx.imageSmoothingQuality="high";
        ctx.drawImage(src,0,0,w,h);
        setProgress(75,"Encoding image...");
        encodeAndFinalize(dst,w,h);
    }

    /* ===== ENCODE TO BLOB & FINALIZE ===== */
    function encodeAndFinalize(canvas,w,h){
        var format=outputFormat.value;
        var quality=qualitySlider.value/100;
        if(format==="image/png"){
            quality=undefined;
        }
        try{
            canvas.toBlob(function(blob){
                if(!blob){
                    notify("Failed to encode image. Your browser may not support this format.",true);
                    progressSection.style.display="none";
                    resizeBtn.disabled=false;
                    return;
                }
                setProgress(100,"Done!");
                if(blobURL)URL.revokeObjectURL(blobURL);
                blobURL=URL.createObjectURL(blob);
                var origSize=formatSize(originalFile?originalFile.size:0);
                var newSize=formatSize(blob.size);
                var ext={"image/jpeg":".jpg","image/png":".png","image/webp":".webp"}[format]||".jpg";
                var baseName=originalFile?originalFile.name.replace(/\.[^.]+$/,""):"image";
                resultInfo.textContent=w+" x "+h+" \u2022 "+origSize+" \u2192 "+newSize;
                resultPreview.src=blobURL;
                resultDownloadBtn.href=blobURL;
                resultDownloadBtn.download=baseName+"_resized_"+w+"x"+h+ext;
                progressSection.style.display="none";
                resizeBtn.disabled=false;
                downloadBtn.style.display="none";
                resultSection.style.display="";
            },format,quality);
        }catch(err){
            notify("Encoding failed: "+err.message,true);
            progressSection.style.display="none";
            resizeBtn.disabled=false;
        }
    }

    /* ===== RESET ===== */
    resetBtn.addEventListener("click",function(){
        originalFile=null;
        loadedImage=null;
        fileInput.value="";
        settingsPanel.classList.remove("show");
        progressSection.style.display="none";
        resizeBtn.disabled=true;
        downloadBtn.style.display="none";
        resultSection.style.display="none";
        resultPreview.src="";
        previewContainer.innerHTML="";
        originalDims.textContent="0 x 0";
        newDims.textContent="-";
        upscaleWarning.style.display="none";
        transparencyWarning.style.display="none";
        if(blobURL){
            URL.revokeObjectURL(blobURL);
            blobURL=null;
        }
    });
});